export async function restoreOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(restorePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Deleted workspaces whose grace period has closed as of `cutoff`. */
export async function listOrgsArchivedBefore(
  cutoff: IsoTimestamp,
  limit: number,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select()
    .from(organizations)
    .where(and(isNotNull(organizations.archivedAt), lte(organizations.archivedAt, cutoff)))
    .limit(Math.max(1, limit))
    .all();

  return rows.map(toOrganization);
}

/**
 * Permanently removes a workspace and every row that belongs to it. There is
 * no cascade at the schema level, so every org-scoped table is cleared here
 * by hand; sessions are global and only have `activeOrgId` cleared.
 */
export async function purgeOrg(orgId: OrgId): Promise<void> {
  const db = getDb();

  db.delete(webhookDeliveries).where(eq(webhookDeliveries.orgId, orgId)).run();
  db.delete(webhookEndpoints).where(eq(webhookEndpoints.orgId, orgId)).run();
  db.delete(searchIndex).where(eq(searchIndex.orgId, orgId)).run();
  db.delete(rateLimitBuckets).where(eq(rateLimitBuckets.orgId, orgId)).run();
  db.delete(invoices).where(eq(invoices.orgId, orgId)).run();
  db.delete(subscriptions).where(eq(subscriptions.orgId, orgId)).run();
  db.delete(activityEvents).where(eq(activityEvents.orgId, orgId)).run();
  db.delete(notificationPreferences).where(eq(notificationPreferences.orgId, orgId)).run();
  db.delete(notifications).where(eq(notifications.orgId, orgId)).run();
  db.delete(attachments).where(eq(attachments.orgId, orgId)).run();
  db.delete(issueLabels).where(eq(issueLabels.orgId, orgId)).run();
  db.delete(labels).where(eq(labels.orgId, orgId)).run();
  db.delete(issues).where(eq(issues.orgId, orgId)).run();
  db.delete(projectMembers).where(eq(projectMembers.orgId, orgId)).run();
  db.delete(projects).where(eq(projects.orgId, orgId)).run();
