/**
 * Restoring runs off a bare `userId`: a deleted workspace has no `Actor` to
 * resolve, since the sign-in path that produces one already excludes it.
 * `org:restore` is still checked through the normal permission vocabulary by
 * assembling an `Actor` from the caller's (still-live) membership row.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);

  const member = await memberRepo.findMember(orgId, userId);
  if (member === null) throw new NotFoundError("Organization", orgId);

  if (org.archivedAt !== null) {
    const deadline = new Date(org.archivedAt).getTime() +
      DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;
    if (Date.now() > deadline) throw new NotFoundError("Organization", orgId);
  }

  const actor: Actor = { userId, orgId, role: member.role };
  assertCan(actor, "org:restore", orgResource(orgId));

  if (org.archivedAt === null) return org;

  const restored = await orgRepo.restoreOrg(orgId);

  await record(orgId, "organization.restored", {
    actorId: userId,
    subjectKind: "organization",
    subjectId: restored.id,
    projectId: null,
    summary: `${restored.name} restored`,
  });

  await emit("organization.restored", {
    ...envelope(orgId, userId),
    slug: restored.slug,
  });

  return restored;
}

